from marshmallow import Schema, fields, ValidationError, validates, validates_schema


class SignupSchema(Schema):
    username = fields.String(required=True)
    email = fields.Email(required=True)
    plan = fields.String(load_default="free")
    age = fields.Integer(required=False)

    @validates("username")
    def validate_username(self, value: str) -> None:
        if not value.isalnum():
            raise ValidationError("Must be alphanumeric")

    @validates("plan")
    def validate_plan(self, value: str) -> None:
        if value not in {"free", "pro", "team"}:
            raise ValidationError('Must be one of "free", "pro", "team"')

    @validates("age")
    def validate_age(self, value: int) -> None:
        if not (16 <= value <= 120):
            raise ValidationError("Must be between 16 and 120 inclusive")

    @validates_schema
    def remove_unknown(self, data, **kwargs):
        # marshmallow by default drops unknown fields if unknown=EXCLUDE is set,
        # but since we didn't set it, we do nothing here.
        # Instead, we rely on the default behavior of Schema.load with unknown=EXCLUDE.
        pass


def validate_signup(data: dict) -> dict:
    schema = SignupSchema(unknown="exclude")
    try:
        result = schema.load(data)
    except ValidationError as err:
        # err.messages is a dict of field -> list of error messages
        ve = ValueError("Invalid input")
        ve.messages = err.messages
        raise ve
    return result
